'use strict';
let shopTab='buy',shopCategory='All',placingItem=null,shopReturn='home',shopNotice='Play the game. Earn stars. Make this shop yours!';
function shopArt(item,size=112){
 if(!item)return '';
 if(item.kind==='item')return `<img class="sticker-art" src="stickers/${item.id}.webp" width="${size}" height="${size}" alt="" aria-hidden="true" draggable="false" decoding="async">`;
 return `<svg class="sticker-swatch" viewBox="0 0 120 112" width="${size}" height="${size}" aria-hidden="true" focusable="false"><rect x="14" y="10" width="92" height="92" rx="22" fill="white"/><rect x="21" y="17" width="78" height="78" rx="16" fill="${item.colour}" stroke="#493552" stroke-width="3"/><path d="M30 77l48-48m-35 57 43-43" fill="none" stroke="white" stroke-opacity=".45" stroke-width="8"/><path d="M76 20l3 8 8 3-8 3-3 8-3-8-8-3 8-3z" fill="#fff9d8" stroke="#493552" stroke-width="1.5"/></svg>`;
}
function updateWalletUI(){const saved=starShop.snapshot();const count=$('#wallet-count');if(count)count.textContent=saved.balance;$('#my-shop')?.setAttribute('aria-label',`My shop. ${saved.balance} saved stars`)}
function earnShopStars(id,amount){const added=starShop.credit(id,amount);updateWalletUI();return added}
function openShop(){
  if(spinning){say('The wheel is spinning. Your shop will be ready in a moment.');return}
  if(screen!=='shop'){shopReturn=screen;if(screen==='question')numberDraft=$('#number-answer')?.value||''}
  stopSpeech();screen='shop';showShop();goTop();
}
function closeShop(){placingItem=null;placingDraft=null;stopSpeech();const back=shopReturn;screen=back;if(back==='question'&&state)renderQuestion();else if(back==='wheel'&&state)showWheel();else if(back==='finish'&&state)finish();else home();goTop()}
function roomHTML(saved){return freeRoomHTML(saved)}
function showShop(){
  screen='shop';const saved=starShop.snapshot();updateWalletUI();const categories=['All','Furniture','Clothes','Decor','Colours'];const items=SHOP_ITEMS.filter(item=>(shopTab==='owned'?saved.owned.includes(item.id):item.price>0)&&(shopCategory==='All'||shopCategory===item.category));
  app.innerHTML=`<div class="shop-heading"><div><div class="eyebrow">Your stars. Your style.</div><h1>My Star Shop</h1><p>Earn stars. Buy items. Make it yours.</p></div><button class="secondary" id="shop-back">← ${shopReturn==='home'?'Back to game':shopReturn==='finish'?'Back to my stars':'Back to my show'}</button></div><div class="shop-layout"><section class="shop-room-card" aria-label="Your decorated shop"><div class="room-toolbar"><span><span aria-hidden="true">🏪</span> ${text(saved.name)}</span><div class="room-toolbar-actions"><button class="shop-read" id="read-shop">◖♪ Read to me</button><button class="small-action" id="rename-shop">Change name ✎</button></div></div>${roomHTML(saved)}${placementInstructionHTML()}</section><aside class="shop-wallet"><div class="wallet-label">MY SAVED STARS</div><div class="wallet-number"><span aria-hidden="true">★</span> ${saved.balance}</div><p>Spend some.<br>Save some for later.</p><button class="primary" id="earn-more">Earn more stars ↗</button><div class="wallet-note" id="shop-notice" role="status">${text(shopNotice)}</div><div class="saving-note"><span aria-hidden="true">${starShop.persistent?'✓':'ⓘ'}</span> ${starShop.persistent?'Saved in this browser.':'Saving is unavailable. This visit only.'}<br><span>Use this browser to visit your shop again.</span></div></aside></div><section class="shop-market" aria-labelledby="market-title"><div class="market-heading"><div><h2 id="market-title">${shopTab==='buy'?'A little something for your shop':'Your collection'}</h2><p>${shopTab==='buy'?'Pick an item. Check the price. Make it yours.':'You own these items. Use them as often as you like.'}</p></div><div class="shop-tabs" aria-label="Item list"><button id="buy-tab" aria-pressed="${shopTab==='buy'}">Buy items</button><button id="owned-tab" aria-pressed="${shopTab==='owned'}">My items <span>${saved.owned.length}</span></button></div></div><div class="shop-categories" aria-label="Item categories">${categories.map(c=>`<button data-category="${c}" aria-pressed="${shopCategory===c}">${c}</button>`).join('')}</div>${shopTab==='owned'&&shopCategory==='Colours'?`<div class="basic-colours"><span>Free colours:</span><button id="basic-wall" class="small-action">Cream walls</button><button id="basic-floor" class="small-action">Wood floor</button></div>`:''}<div class="shop-item-grid">${items.length?items.map(item=>{const owned=saved.owned.includes(item.id),placed=!!saved.positions[item.id],used=item.kind!=='item'&&saved[item.kind]===item.value;return `<article class="shop-item-card ${placingItem===item.id?'chosen':''}"><div class="item-art" style="--item-colour:${item.colour}">${shopArt(item,112)}${owned?'<span class="owned-tick">✓ Yours</span>':''}</div><div class="item-card-info"><span class="item-kind">${item.kind==='wall'?'Wall colour':item.kind==='floor'?'Floor colour':item.category}</span><h3>${text(item.name)}</h3><div class="item-card-bottom"><span class="item-cost">${item.price===0?'Free':`★ ${item.price}`}</span><button class="${owned?'use-button':'buy-button'}" data-item="${item.id}" ${used?'disabled':''} aria-label="${owned?(used?'Using ':placed?'Move ':'Use '):'Buy '}${text(item.name)}${owned?'':' for '+item.price+(item.price===1?' star':' stars')}">${owned?(used?'Using ✓':placed?'Move':'Use item'):saved.balance>=item.price?'Buy':'Save '+(item.price-saved.balance)+' more'}</button></div></div></article>`}).join(''):'<p class="empty">No items here yet. Earn stars and choose something you like.</p>'}</div></section>`;
  bind('read-shop',()=>read('Welcome to your shop. You have '+starShop.snapshot().balance+' saved stars. Choose an item. Check the price. Tap Buy. Then tap anywhere in your shop to place it. Drag items to move them, or use the arrow buttons. You can save your stars for later.'));bind('shop-back',closeShop);bind('earn-more',()=>{shopReturn==='question'||shopReturn==='wheel'?closeShop():home();goTop()});bind('rename-shop',renameShop);bind('cancel-place',()=>{placingItem=null;placingDraft=null;showShop()});bind('buy-tab',()=>{shopTab='buy';shopCategory='All';showShop()});bind('owned-tab',()=>{shopTab='owned';shopCategory='All';showShop()});bind('basic-wall',()=>{starShop.theme('wall','cream');showShop()});bind('basic-floor',()=>{starShop.theme('floor','oak');showShop()});document.querySelectorAll('[data-category]').forEach(button=>button.onclick=()=>{shopCategory=button.dataset.category;showShop()});document.querySelectorAll('[data-item]').forEach(button=>button.onclick=()=>chooseShopItem(button.dataset.item));bindRoomPlacement();
}
function chooseShopItem(id){const item=SHOP_ITEM_MAP[id];if(!item)return;const saved=starShop.snapshot();if(saved.owned.includes(id)){if(item.kind==='item'){beginPlacing(id)}else{placingItem=null;placingDraft=null;starShop.theme(item.kind,item.value);shopNotice='Now using '+item.name.toLowerCase()+'.';showShop();say(shopNotice)}return}
  if(saved.balance<item.price){const need=item.price-saved.balance;openDialog(`<h2>Keep saving!</h2><div class="purchase-art">${shopArt(item,120)}</div><p>A ${text(item.name.toLowerCase())} costs <strong>${item.price} stars</strong>.</p><p>You have <strong>${saved.balance} stars</strong>.<br>Save <strong>${need} more ${need===1?'star':'stars'}</strong> to buy it.</p><button class="primary" id="keep-saving">Keep saving ★</button>`);bind('keep-saving',()=>$('#dialog').close());return}
  openDialog(`<h2>Buy ${text(item.name.toLowerCase())}?</h2><div class="purchase-art">${shopArt(item,120)}</div><div class="purchase-maths"><div><span>You have</span><strong>★ ${saved.balance}</strong></div><span aria-hidden="true">−</span><div><span>Cost</span><strong>★ ${item.price}</strong></div><span aria-hidden="true">=</span><div><span>Stars left</span><strong>★ ${saved.balance-item.price}</strong></div></div><div class="purchase-actions"><button class="primary" id="confirm-buy">Buy for ${item.price} ${item.price===1?'star':'stars'}</button><button class="secondary" id="not-now">Not now</button></div>`);bind('not-now',()=>$('#dialog').close());bind('confirm-buy',()=>purchaseShopItem(id));
}
function purchaseShopItem(id){const result=starShop.buy(id);$('#dialog').close();if(!result.ok){shopNotice=result.reason==='owned'?'You already own this item. Use it from My items.':'You need more stars for this item.';showShop();say(shopNotice);return}initAudio();sfx(true);placingItem=result.item.kind==='item'?id:null;placingDraft=placingItem?{x:50,y:70}:null;shopNotice=`${result.before} − ${result.cost} = ${result.left}. You bought ${result.item.name.toLowerCase()}! ${placingItem?'Tap anywhere in your shop to place it.':''}`;showShop();say(shopNotice);$('.shop-room-card')?.scrollIntoView({behavior:'smooth',block:'start'});if(placingItem)$('#place-here')?.focus({preventScroll:true})}
function renameShop(){const saved=starShop.snapshot();openDialog(`<h2>Name your shop</h2><label class="shop-name-label" for="shop-name-input">Shop name</label><input class="shop-name-input" id="shop-name-input" maxlength="24" value="${text(saved.name)}" autocomplete="off"><p class="micro">Use up to 24 characters.</p><button class="primary" id="save-shop-name">Save name ✓</button>`);bind('save-shop-name',()=>{if(!starShop.rename($('#shop-name-input').value)){say('Type a name for your shop.');return}$('#dialog').close();showShop();say('Shop name saved.')})}
const IPAD_GAME_URL='https://retail-showtime-classroom-7k4.abubakarhasyim18.chatgpt.site';
function shareIPads(){openDialog(`<h2>Open on an iPad</h2><div class="ipad-link"><img class="ipad-qr" src="ipad-qr.png" width="200" height="200" alt="QR code for the Retail Showtime game"><div><p><strong>Scan with the iPad camera.</strong><br>Tap the link that appears.<br>No sign-in is needed.</p><a href="${IPAD_GAME_URL}" target="_blank" rel="noopener">Open the game ↗</a></div></div><label class="micro" for="ipad-url">Student game link</label><input id="ipad-url" class="ipad-url" readonly value="${IPAD_GAME_URL}"><div class="ipad-dialog-actions"><button class="primary" id="copy-ipad-link">Copy game link</button><a href="ipad-qr.png" download="Retail-Showtime-iPad-QR.png">Save QR code ↓</a></div><p class="ipad-status" id="ipad-copy-status" role="status"></p><h3>Add to the Home Screen</h3><ol class="ipad-steps"><li>Open the game in <strong>Safari</strong>.</li><li>Tap <strong>Share</strong>.</li><li>Tap <strong>Add to Home Screen</strong>, then <strong>Add</strong>.</li></ol><p class="micro">Use the same browser or Home Screen shortcut each time. Stars and decorations save on that iPad. Different devices have separate shops. An internet connection is needed to load the game.</p>`);bind('copy-ipad-link',async()=>{try{await navigator.clipboard.writeText(IPAD_GAME_URL);$('#ipad-copy-status').textContent='Link copied. Paste it into your class app or message.'}catch{$('#ipad-url').focus();$('#ipad-url').select();$('#ipad-copy-status').textContent='Touch and hold the selected link. Then tap Copy.'}})}
